-- This returns rows:
SELECT COUNT(*) FROM VW_INV_BIN_V1 WHERE PLANT = '03';

-- This returns 0. It looks like a valid query. It is the footgun.
SELECT COUNT(*) FROM VW_INV_BIN_V1 WHERE PLANT = 3;

-- This also returns 0 if your session did something clever with padding:
SELECT COUNT(*) FROM VW_INV_BIN_V1 WHERE TRIM(PLANT) = '3';

-- Java. Right:
PreparedStatement ps = conn.prepareStatement(
    "SELECT ... FROM VW_INV_BIN_V1 WHERE PLANT = ?");
ps.setString(1, plantCode.getValue()); // "01"

-- Java. Wrong. Do not. I reviewed a PR that did this on January 29.
ps.setInt(1, Integer.parseInt(plantCode.getValue()));
